// Oblate-ellipsoid LCC fixture (V1.1 phase 4): Code Table 3.2 byte 3 with the
// earth axes declared INLINE in section 3 (WGS 84: 6378.137 / 6356.75231 km).
// Validates that the reader takes the axes from the FILE (not the CT table guess)
// and that the OBLATE projection branch agrees with wgrib2 -ll2ij, which is
// what makes the conformal wind-rotation angle correct on a non-spherical earth.
//
// ij_checks mirror tests/fixtures/expected.json (hrrr_ellip_small.grib2),
// regenerated by scripts/regen_expected.sh. wgrib2 returns 1-based i and j
// counted from the SOUTH edge; storage convention is 0-based with row 0 at La1
// (north edge here, scan byte 0):  i_store = i_wg - 1, j_store = ENY - j_wg.

use wx_ingest::grib2::{decode_file, ParamFilter, grid_winds};
use wx_core::grid::{GridDef};

const ENX: usize = 41;
const ENY: usize = 31;

fn fixture_path(name: &str) -> String {
    return format!("../../tests/fixtures/{name}");
}

fn abs_diff(a: f64, b: f64) -> f64 {
    let d = a - b;
    if d < 0.0 {
        return -d;
    }
    return d;
}

// lon, lat, i_wg, j_wg (wgrib2 -ll2ij on this fixture)
const IJ: [[f64; 4]; 16] = [
    [250.000000, 40.000000, 1.000000, 31.000000],
    [250.000000, 36.800000, 5.425399, 1.789469],
    [252.750000, 38.400000, 22.922728, 19.644796],
    [251.000000, 39.500000, 8.768914, 27.536019],
    [254.500000, 37.500000, 37.027108, 13.858582],
    [251.203240, 37.922650, 12.561256, 13.394647],
    [254.507720, 37.038600, 37.909356, 9.696352],
    [253.065020, 38.240330, 25.439801, 18.603660],
    [253.359050, 38.245570, 27.535672, 19.039756],
    [250.153230, 39.741530, 2.439771, 28.800622],
    [253.373480, 37.630550, 28.678097, 13.480531],
    [251.299880, 38.227940, 12.799965, 16.288812],
    [250.116720, 38.445050, 3.990323, 16.919197],
    [253.266350, 37.571420, 28.004753, 12.800778],
    [250.797550, 38.709540, 8.488969, 20.093534],
    [251.582960, 38.593490, 14.274598, 19.954924],
];

#[test]
fn ellipsoid_axes_come_from_the_file() {
    let r = decode_file(fixture_path("hrrr_ellip_small.grib2"), ParamFilter::All);
    match r {
        Err(_e) => { assert!(false); }
        Ok((msgs, st)) => {
            assert!(msgs.len() == 3);
            assert!(st.messages_total == 3);
            // order: UGRD, VGRD (grid-relative grids), TMP (earth-relative grid)
            for x in 0 .. 3 {
                let wg = x < 2;
                assert!(msgs[x].winds_grid == wg);
                assert!(grid_winds(&msgs[x].grid) == wg);
                match msgs[x].grid {
                    GridDef::Lambert(ref gl) => {
                        // CT 3.2 byte 3 = user-defined spheroid: the axes are
                        // INLINE in section 3 and must be read from there.
                        assert!(gl.earth_shape == 3);
                        assert!(gl.inline_axes);
                        assert!(abs_diff(gl.r_major, 6378137.0) <= 1e-6);
                        assert!(abs_diff(gl.r_minor, 6356752.31) <= 1e-6);
                        // oblate branch really is active
                        assert!(gl.e > 0.05 && gl.e < 0.1);
                        // and the flag bit survives on the wind grids only
                        assert!(gl.winds_grid == wg);
                    }
                    GridDef::Regular(ref _rg) => { assert!(false); }
                    GridDef::Gaussian(ref _gg) => { assert!(false); }
                }
            }
            // analytic values: base 255 + param offset + j*100 + i
            let offs: [f64; 3] = [4000.0, 8000.0, 0.0];
            for x in 0 .. 3 {
                assert!(msgs[x].data.len() == ENX * ENY);
                for j in 0 .. ENY {
                    for i in 0 .. ENX {
                        let k = j * ENX + i;
                        let want = (255.0 + offs[x] + (j * 100) as f64 + (i as f64)) as f32;
                        assert!(msgs[x].data[k] == want);
                    }
                }
            }
        }
    }
}

#[test]
fn oblate_projection_matches_wgrib2_ll2ij() {
    // spec §9.2 extended to the OBLATE earth shape: corners + center + random
    // probes, within 1e-4 grid units of wgrib2's own answer.
    let r = decode_file(fixture_path("hrrr_ellip_small.grib2"), ParamFilter::All);
    match r {
        Err(_e) => { assert!(false); }
        Ok((msgs, _st)) => {
            let gd = &msgs[0].grid;
            for row in &IJ {
                let p = gd.project(row[1], row[0]);
                match p {
                    None => { assert!(false); }
                    Some((di, dj)) => {
                        assert!(abs_diff(di + 1.0, row[2]) <= 1e-4);
                        assert!(abs_diff((ENY as f64) - dj, row[3]) <= 1e-4);
                    }
                }
            }
        }
    }
}

#[test]
fn oblate_rotation_and_inverse_roundtrip_at_nodes() {
    // rot_angle_deg must agree with the cone relation on the oblate grid, and
    // inverse(project(lat,lon)) must return to the node -- both at the four
    // domain corners and the center.
    let r = decode_file(fixture_path("hrrr_ellip_small.grib2"), ParamFilter::All);
    match r {
        Err(_e) => { assert!(false); }
        Ok((msgs, _st)) => {
            match msgs[0].grid {
                GridDef::Lambert(ref gl) => {
                    let pts: [[f64; 2]; 5] = [
                        [0.0, 0.0], [40.0, 0.0], [0.0, 30.0], [40.0, 30.0],
                        [20.0, 15.0],
                    ];
                    for pt in &pts {
                        let (lat, lon) = gl.inverse(pt[0], pt[1]);
                        let back = gl.project(lat, lon);
                        match back {
                            None => { assert!(false); }
                            Some((di, dj)) => {
                                assert!(abs_diff(di, pt[0]) <= 1e-6);
                                assert!(abs_diff(dj, pt[1]) <= 1e-6);
                            }
                        }
                        // bearing of grid +i from true north: 90 deg plus the
                        // meridian convergence angle ns*(lon - LoV)
                        let dl = (lon - gl.lov + 540.0) % 360.0 - 180.0;
                        let want = 90.0 + gl.ns * dl;
                        let got = gl.rot_angle_deg(pt[0], pt[1]);
                        assert!(abs_diff(got, want) <= 1e-9);
                        // northern-hemisphere secant conic: +i points east-ish,
                        // tilted north of due east everywhere in this domain
                        assert!(got > 90.0 && got < 105.0);
                    }
                }
                GridDef::Regular(ref _rg) => { assert!(false); }
                GridDef::Gaussian(ref _gg) => { assert!(false); }
            }
        }
    }
}
